import { ProgressUnit } from '@reading/shared';
import {
  IsEnum,
  IsInt,
  IsISO8601,
  IsUUID,
  Matches,
  Max,
  Min,
} from 'class-validator';

// ISO 8601 allows "2026-10-16T17:22:00" with no zone, which the server would
// read in its own timezone. Requiring Z or ±hh:mm makes the moment exact.
const WITH_TIMEZONE = /(Z|[+-]\d{2}:\d{2})$/;
const timezoneMessage = {
  message: '$property must end with a timezone, e.g. Z or +03:00',
};

export class CreateReadingSessionDto {
  // Generated by the app; the same value sent again returns the saved session
  @IsUUID()
  clientId: string;

  @IsUUID()
  userBookId: string;

  // Full timestamps with a timezone, e.g. 2026-10-16T18:00:00.000Z
  @IsISO8601({ strict: true, strictSeparator: true })
  @Matches(WITH_TIMEZONE, timezoneMessage)
  startedAt: string;

  @IsISO8601({ strict: true, strictSeparator: true })
  @Matches(WITH_TIMEZONE, timezoneMessage)
  endedAt: string;

  @IsInt()
  @Min(1)
  @Max(24 * 60 * 60)
  durationSec: number;

  @IsEnum(ProgressUnit)
  unit: ProgressUnit;

  @IsInt()
  @Min(0)
  @Max(100_000)
  progressFrom: number;

  @IsInt()
  @Min(0)
  @Max(100_000)
  progressTo: number;
}
